import{z as n,x as s,o as A,c as p,q as l,j as o,D as t,d as a,s as r,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"长上下文的 KV 预算","description":"","frontmatter":{"title":"长上下文的 KV 预算","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-longcontext-budget.md","filePath":"llm/kv-longcontext-budget.md","lastUpdated":1791413859000}'),d={name:"llm/kv-longcontext-budget.md"};function m(D,E,C,h,f,c){const B=s("Mermaid");return A(),p("div",null,[E[2]||(E[2]=l('<h1 id="长上下文的-kv-预算" tabindex="-1">长上下文的 KV 预算 <a class="header-anchor" href="#长上下文的-kv-预算" aria-label="Permalink to &quot;长上下文的 KV 预算&quot;">​</a></h1><div class="epigraph"><p>「支持 128K」是能力声明，不是容量声明；预算表不编出来，长上下文就在第六十个并发请求上替你做决定。</p><footer>—— 据 Pope et al., 2022 的推理扩展会计口径整理</footer></div><p>压缩单元把刀凑齐了：<a href="/llm/kv-quant-int8-int4">量化</a>、<a href="/llm/kv-layerwise-sensitivity">逐层配额</a>、<a href="/llm/kv-eviction-heuristics">驱逐</a>、<a href="/llm/kv-merge-distill">合并</a>。系统交互单元先问分配：一张卡的 HBM 里，权重、页池、上下文、余量怎么切？一条 128K 的请求值得多少份额？本课把生命周期、分页、共享与压缩四刀装进同一张预算表。字节的公式<a href="/llm/kv-cache-size-math">早已写出</a>，本课不重推，只做代入与决策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长上下文先撞墙的地方是容量：KV 随长度线性涨，权重是常数，变量先击穿池子。预算缺位的表现是两头挨打：接单时不知道能不能装下，凭「支持 128K」承诺满并发；跑到一半 OOM，靠抢占和重算还账。另一张墙是带宽：decode 每步要把全部可见 KV 从 HBM 扫一遍，128K 的满长请求哪怕只生成一个字，也要先付一遍全量扫描。两张墙都随 \\(n\\) 线性，产品表现完全不同——前者是 429 与 OOM，后者是「还能聊，但一个字两百毫秒」。预算必须两张都编。</p><p><span class="marginnote">术语翻译：p50 / p95 / p99 是把所有请求按长度从小到大排队后的「名次」——p95 就是第 95% 那名请求的长度。用 p50 编预算等于一半请求都装不下，所以吞吐看 p50、容量看 p95、逃生路径只为 p99 做准备。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算编制五步。</p><p><strong>一、固定项</strong>。权重、CUDA 上下文、激活与专家池先扣掉，剩下的才是 KV 池；页池水位再留一截给抢占与增长（口径见<a href="/llm/kv-paging-fragmentation">分页课</a>）。</p><p><strong>二、单请求账</strong>。代入 \\(\\mathrm{KV}=2Ln h_{kv} d b\\)，再乘本系统各刀的实际压缩：精度因子（量化后有效 \\(b\\)）、驱逐后的长度、合并率。产出一张「每 token 有效字节」表，按位置分层列——统一价目做不了精细预算。</p><p><strong>三、负载画像</strong>。长度分布用分位数：p50 编吞吐、p95 编容量、p99 编逃生路径。页池没有「平均请求」，按均值编预算等于给 p99 请求预埋 OOM。</p><p><strong>四、并发上限</strong>。池子除以分位请求账，得同时服务的满长请求数；再乘前缀<a href="/llm/kv-prefix-cache">共享</a>的分叉折扣——共享提示只付一份，生成段各付各的。</p><p><span class="marginnote">数字实例：8 个请求共享同一段 4K 的系统提示、各自再生成 2K——不共享要付 \\(8 \\times 6\\mathrm{K}\\) 份 KV；共享后提示只付 1 份，实付 \\(4\\mathrm{K} + 8 \\times 2\\mathrm{K} = 20\\mathrm{K}\\) 份，省下近六成。共享折扣只在同副本路由下兑现。</span></p><p><strong>五、逃生顺序</strong>。超出预算时按「无损 → 近似 → 搬家 → 不服务」降级：先 8-bit，再逐层配额与驱逐，再 <a href="/llm/kv-offload">offload</a> 与<a href="/llm/kv-tiered-storage">分层存储</a>，最后拒绝。顺序的理由是误差性质：量化的噪声远小于误杀，搬家的代价是带宽不是正确性。</p>',14)),(A(),o(i,null,{default:t(()=>[r(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20CARD%5B%22%E5%8D%A1%EF%BC%9AHBM%20%E5%AE%B9%E9%87%8F%E4%B8%8E%E5%B8%A6%E5%AE%BD%22%5D%20--%3E%20POOL%5B%22%E6%89%A3%E6%9D%83%E9%87%8D%E4%B8%8E%E5%B8%B8%E9%87%8F%EF%BC%8C%E5%BE%97%20KV%20%E6%B1%A0%22%5D%0A%20%20POOL%20--%3E%20ACCT%5B%22%E5%8D%95%E8%AF%B7%E6%B1%82%E8%B4%A6%EF%BC%9A%E5%85%AC%E5%BC%8F%20%C3%97%20%E9%87%8F%E5%8C%96%20%C3%97%20%E9%A9%B1%E9%80%90%20%C3%97%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20LOAD%5B%22%E8%B4%9F%E8%BD%BD%E5%88%86%E4%BD%8D%E6%95%B0%20p50%20%2F%20p95%20%2F%20p99%22%5D%20--%3E%20ACCT%0A%20%20ACCT%20--%3E%20CAP%5B%22%E5%B9%B6%E5%8F%91%E4%B8%8A%E9%99%90%20%3D%20%E6%B1%A0%20%C3%B7%20%E5%88%86%E4%BD%8D%E8%B4%A6%20%C3%B7%20%E5%85%B1%E4%BA%AB%E6%8A%98%E6%89%A3%22%5D%0A%20%20ACCT%20--%3E%20BW%5B%22decode%20%E5%B8%A6%E5%AE%BD%E8%B4%A6%EF%BC%9A%E6%AF%8F%E6%AD%A5%E6%89%AB%E5%85%A8%E9%83%A8%E5%8F%AF%E8%A7%81%20KV%22%5D%0A%20%20CAP%20--%3E%20ESC%7B%22%E8%B6%85%E9%A2%84%E7%AE%97%3F%22%7D%0A%20%20BW%20--%3E%20ESC%0A%20%20ESC%20--%3E%7C%E6%98%AF%7C%20DOWN%5B%22%E9%99%8D%E7%BA%A7%EF%BC%9A8-bit%20%E2%86%92%20%E9%85%8D%E9%A2%9D%2F%E9%A9%B1%E9%80%90%20%E2%86%92%20offload%20%E2%86%92%20%E6%8B%92%E7%BB%9D%22%5D%0A%20%20ESC%20--%3E%7C%E5%90%A6%7C%20SERVE%5B%22%E6%8C%89%E6%B0%B4%E4%BD%8D%E6%8E%A5%E5%8D%95%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("两张账分开记的理由在产品语义。容量账错了一格是拒绝率，带宽账错了一格是 TPOT；前者可以靠降级和排队救，后者直接写进每一轮的用户体感。带宽账的机制在"),e("a",{href:"/llm/arithmetic-intensity-decode"},"算术强度"),a("：decode 是瘦计算、胖加载，每步时间近似等于读完全部 KV 加权重的时间，所以「每 token 有效字节」表同时是容量表和时间表——压一半字节，池子翻倍、TPOT 减半，一张表两处兑现。长上下文把这层关系放大到不可忽略：满长请求的 KV 扫描可以从「零头」涨到「每步的主要项」，"),e("a",{href:"/llm/decode-memory-wall"},"decode 显存墙"),a(" 的那一课在 128K 处从背景变成了主旋律。")],-1)),(A(),o(i,null,{default:t(()=>[r(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E9%95%BF%E5%BA%A6%20n%20%E5%8F%98%E9%95%BF%22%5D%20--%3E%20C1%5B%22%E5%AE%B9%E9%87%8F%E5%A2%99%3A%20KV%20%E6%B1%A0%E8%A2%AB%E6%8C%A4%E7%A9%BF%22%5D%0A%20%20N%20--%3E%20B1%5B%22%E5%B8%A6%E5%AE%BD%E5%A2%99%3A%20%E6%AF%8F%E6%AD%A5%E8%A6%81%E6%89%AB%E7%9A%84%E5%AD%97%E8%8A%82%E5%8F%98%E5%A4%9A%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E7%97%87%E7%8A%B6%3A%20429%20%E6%8B%92%E7%BB%9D%20%2F%20%E6%8A%A2%E5%8D%A0%20%2F%20OOM%22%5D%0A%20%20C2%20--%3E%20C3%5B%22%E6%95%91%E6%B3%95%3A%20%E9%99%8D%E7%BA%A7%E4%B8%8E%E6%8E%92%E9%98%9F%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E7%97%87%E7%8A%B6%3A%20%E4%B8%80%E4%B8%AA%E5%AD%97%E4%B9%9F%E8%A6%81%E7%AD%89%E4%B8%A4%E7%99%BE%E6%AF%AB%E7%A7%92%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E6%95%91%E6%B3%95%3A%20%E5%8E%8B%E5%AD%97%E8%8A%82%2C%20%E5%87%8F%E5%8D%8A%E5%8D%B3%20TPOT%20%E8%BF%91%E5%8D%8A%22%5D%0A%20%20C3%20--%3E%20T%5B%22%E5%90%8C%E4%B8%80%E5%BC%A0%E3%80%8E%E6%AF%8F%20token%20%E6%9C%89%E6%95%88%E5%AD%97%E8%8A%82%E3%80%8F%E8%A1%A8%2C%20%E4%B8%A4%E5%A4%84%E5%85%91%E7%8E%B0%22%5D%0A%20%20B3%20--%3E%20T%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">代入感受量级：Llama-3-8B（32 层、8 KV 头、FP16）每 token 128 KiB，128K 上下文一条就是 16 GiB——80 GiB 的卡扣掉 16 GiB 权重后，满长并发只剩两三条。先量化到 8-bit 再谈并发，不是优化，是及格线。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预算随模型、精度、页大小、压缩策略版本化，升级模型必须重编，旧表不能沿用。投机解码会放大长度方差（接受长度不确定），预算要留回滚余量，这是下一课的主题。共享的折扣只在同副本上兑现，路由把同前缀打散时折扣作废。on-device 场景的预算更紧，口径相同而常数不同（见<a href="/llm/on-device-kv">端侧 KV 预算</a>）。最后，「最大上下文」是窗口声明，绝不能当成常驻预留——那是<a href="/llm/paged-attention">分页</a>之前的老错误，别在预算表里复发。</p><p><span class="marginnote">常见误区：「最大上下文 128K」是模型窗口的声明，不是给你预留的显存。把它当常驻预留编进预算，会在真实负载到来之前就占死池子；窗口只回答「一条最长能算多长」，预算表才回答「同时能接几条」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预算两张表：容量（并发上限、拒绝率）与带宽（每步扫描时间），都随长度线性、语义不同。</li><li>编制五步：扣常量、单请求账、负载分位数、并发上限、逃生顺序。</li><li>单请求账 = 公式 × 量化 × 驱逐 × 合并；统一价目做不了精细预算。</li><li>分位数会计：p50 编吞吐、p95 编容量、p99 编逃生；均值会埋雷。</li><li>降级顺序按误差性质：8-bit → 配额/驱逐 → offload → 拒绝。</li><li>出处：Pope et al., 2022；公式与墙的口径据本仓库 KV 大小计算、算术强度课。</li></ul>',6))])}const k=n(d,[["render",m]]);export{g as __pageData,k as default};
